package app.rwun;

import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.graphics.*;import android.view.*;import android.widget.*;import java.net.*;import java.io.*;import java.util.*;import java.util.concurrent.*;

/** Native, opt-in online route map. Fetches only the displayed viewport; no area downloads. */
public final class StreetMapActivity extends Activity {
  private final ExecutorService loader=Executors.newSingleThreadExecutor();private MapView map;
  public void onCreate(Bundle state){super.onCreate(state);var p=new UiKit.Palette(true);LinearLayout root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(p.background);root.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i.consumeSystemWindowInsets();});
    root.addView(UiKit.action(this,p,"Back",this::finish));try{map=new MapView(TrackingService.readRoute(this,getIntent().getStringExtra("route")));root.addView(map,new LinearLayout.LayoutParams(-1,0,1));LinearLayout zoom=new LinearLayout(this);zoom.addView(UiKit.action(this,p,"Zoom in",()->map.zoom(1)),new LinearLayout.LayoutParams(0,-2,1));zoom.addView(UiKit.action(this,p,"Zoom out",()->map.zoom(-1)),new LinearLayout.LayoutParams(0,-2,1));root.addView(zoom);
    TextView credit=UiKit.label(this,"© OpenStreetMap contributors · map data & licence",12,p.ink,false);credit.setPadding(16,16,16,16);credit.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse("https://www.openstreetmap.org/copyright"))));root.addView(credit);setContentView(root);
    new AlertDialog.Builder(this).setTitle("Load an online street map?").setMessage("OpenStreetMap receives tile requests for the area you view and your network address. Your route overlay stays on this phone. Tiles are cached for at least seven days when available. This does not download an offline map or provide turn-by-turn navigation.").setNegativeButton("Cancel",(d,w)->finish()).setPositiveButton("Load map",(d,w)->{map.enabled=true;map.fetch();}).show();
    }catch(Exception e){root.addView(UiKit.label(this,UserErrors.message(e),16,p.ink,false));setContentView(root);}}
  protected void onDestroy(){loader.shutdownNow();super.onDestroy();}
  private final class MapView extends View {
    final List<ActivityFiles.Sample> points;final Map<String,Bitmap> images=new ConcurrentHashMap<>();final Set<String> pending=ConcurrentHashMap.newKeySet();final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);double cx,cy;int z=13;boolean enabled,tileFailed;float lastX,lastY;
    MapView(List<ActivityFiles.Sample> points){super(StreetMapActivity.this);this.points=points;setContentDescription("Street map of the recorded route. Drag to pan; zoom buttons change scale.");if(!points.isEmpty()){cx=x(points.get(0).lon());cy=y(points.get(0).lat());}}
    double x(double lon){return (lon+180)/360;}double y(double lat){double rad=Math.toRadians(Math.max(-85.0511,Math.min(85.0511,lat)));return (1-Math.log(Math.tan(rad)+1/Math.cos(rad))/Math.PI)/2;}
    protected void onSizeChanged(int w,int h,int oldW,int oldH){if(points.size()>1){double minX=1,maxX=0,minY=1,maxY=0;for(var point:points){minX=Math.min(minX,x(point.lon()));maxX=Math.max(maxX,x(point.lon()));minY=Math.min(minY,y(point.lat()));maxY=Math.max(maxY,y(point.lat()));}cx=(minX+maxX)/2;cy=(minY+maxY)/2;z=17;while(z>0&&((maxX-minX)*256*(1<<z)>w-40||(maxY-minY)*256*(1<<z)>h-40))z--;}fetch();}
    void zoom(int delta){z=Math.max(0,Math.min(18,z+delta));images.clear();fetch();invalidate();}
    public boolean onTouchEvent(MotionEvent e){if(e.getAction()==MotionEvent.ACTION_DOWN){lastX=e.getX();lastY=e.getY();return true;}if(e.getAction()==MotionEvent.ACTION_MOVE){double world=256.*(1<<z);cx-=(e.getX()-lastX)/world;cy-=(e.getY()-lastY)/world;cx=(cx%1+1)%1;cy=Math.max(0,Math.min(1,cy));lastX=e.getX();lastY=e.getY();invalidate();return true;}if(e.getAction()==MotionEvent.ACTION_UP){performClick();fetch();return true;}return true;}
    public boolean performClick(){super.performClick();return true;}
    void fetch(){if(!enabled||getWidth()==0||loader.isShutdown())return;int zoom=z,n=1<<zoom;double world=256.*n,left=cx*world-getWidth()/2.,top=cy*world-getHeight()/2.;int x0=(int)Math.floor(left/256),x1=(int)Math.floor((left+getWidth())/256),y0=Math.max(0,(int)Math.floor(top/256)),y1=Math.min(n-1,(int)Math.floor((top+getHeight())/256));if((x1-x0+1)*(y1-y0+1)>48)return;
      for(int tx=x0;tx<=x1;tx++)for(int ty=y0;ty<=y1;ty++){int tileX=(tx%n+n)%n,tileY=ty;String key=zoom+"-"+tileX+"-"+tileY;if(images.containsKey(key)||!pending.add(key))continue;
        loader.submit(()->{try{File cache=new File(getCacheDir(),"tile-"+key+".png");if(!cache.exists()||System.currentTimeMillis()-cache.lastModified()>7L*86400*1000){HttpURLConnection connection=(HttpURLConnection)new URL("https://tile.openstreetmap.org/"+zoom+"/"+tileX+"/"+tileY+".png").openConnection();connection.setRequestProperty("User-Agent","OpenRun/0.8 Android");connection.setConnectTimeout(10000);connection.setReadTimeout(10000);try{if(connection.getResponseCode()!=200)throw new IOException();ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=connection.getInputStream()){byte[] block=new byte[4096];int read;while((read=in.read(block))!=-1){if(out.size()+read>1024*1024)throw new IOException();out.write(block,0,read);}}try(FileOutputStream file=new FileOutputStream(cache)){file.write(out.toByteArray());}}finally{connection.disconnect();}}
          Bitmap bitmap=BitmapFactory.decodeFile(cache.getPath());if(bitmap!=null){if(images.size()>64)images.clear();images.put(key,bitmap);postInvalidate();}
        }catch(Exception ignored){tileFailed=true;postInvalidate();}finally{pending.remove(key);}});
      }
    }
    protected void onDraw(Canvas canvas){canvas.drawColor(Color.rgb(37,44,54));if(enabled&&images.isEmpty()){paint.setColor(Color.LTGRAY);paint.setTextSize(13*getResources().getDisplayMetrics().scaledDensity);canvas.drawText(tileFailed?"Tiles unavailable. Check your connection or pan to retry.":"Loading map tiles…",12,28*getResources().getDisplayMetrics().density,paint);}double world=256.*(1<<z),left=cx*world-getWidth()/2.,top=cy*world-getHeight()/2.;int n=1<<z,x0=(int)Math.floor(left/256),x1=(int)Math.floor((left+getWidth())/256),y0=Math.max(0,(int)Math.floor(top/256)),y1=Math.min(n-1,(int)Math.floor((top+getHeight())/256));for(int tx=x0;tx<=x1;tx++)for(int ty=y0;ty<=y1;ty++){Bitmap image=images.get(z+"-"+((tx%n+n)%n)+"-"+ty);if(image!=null)canvas.drawBitmap(image,(float)(tx*256-left),(float)(ty*256-top),paint);}Path path=new Path();int segment=-1;for(var point:points){float px=(float)(x(point.lon())*world-left),py=(float)(y(point.lat())*world-top);if(point.segment()!=segment){path.moveTo(px,py);segment=point.segment();}else path.lineTo(px,py);}paint.setStyle(Paint.Style.STROKE);paint.setStrokeWidth(6);paint.setColor(Color.rgb(0,121,107));canvas.drawPath(path,paint);paint.setStyle(Paint.Style.FILL);}
  }
}
